-- 7.6절과 견준다

// 꺼내 쓰기
@RestController
class A {
    private final Environment env;
    A(Environment env) { this.env = env; }
    @GetMapping("/a") String a() {
        return env.getProperty("study.db.pool-size", Integer.class, 10).toString();
    }
}

// 꽂아 넣기
@RestController
class B {
    private final int poolSize;
    B(@Value("${study.db.pool-size:10}") int poolSize) { this.poolSize = poolSize; }
    @GetMapping("/b") String b() { return String.valueOf(poolSize); }
}

$ java -jar build/libs/app.jar --study.db.pool-size=20 > /dev/null 2>&1 &
$ curl -s localhost:8080/a; echo; curl -s localhost:8080/b
20
20

