-- 꽂히는 시점

@Component
class Timing {
    @Value("${study.mode:none}")
    private String field;

    private final String ctor;

    Timing(@Value("${study.mode:none}") String ctor) {
        this.ctor = ctor;
        System.out.println("[생성자] ctor=" + ctor + " field=" + field);
    }

    @PostConstruct
    void after() {
        System.out.println("[초기화] ctor=" + ctor + " field=" + field);
    }
}

